import * as datePickerMachine from "@zag-js/date-picker";
import { CalendarDate, type DateValue } from "@internationalized/date";
import type { MachineInput } from "marko-zag";
import { buttonVariants } from "../button/variants.ts";
import Icon from "../icon/icon.marko";
import { cn } from "../../../lib/utils.ts";
import { stripOwnProps } from "../../../lib/native-attrs.ts";

// Calendar is an inline, always-open date-picker: `open`/`inline`/
// `closeOnSelect` are fixed by this component, not exposed to callers.
// `value`/`valueChange` use plain { year, month, day } objects instead of
// Zag's DateValue so consumers don't need @internationalized/date.
export type Input = Omit<
  MachineInput<"div", datePickerMachine.Props>,
  "open" | "inline" | "closeOnSelect" | "value" | "min" | "max"
> & {
  /** Selected date(s) as plain objects — one entry per selected date (single mode uses a one-element array). */
  value?: { year: number; month: number; day: number }[];
  /** Fires with the full selection as plain date objects whenever it changes; enables `value:=` two-way binding. */
  valueChange?: (value: { year: number; month: number; day: number }[]) => void;
  /** Earliest selectable date (inclusive); days before it render disabled. */
  min?: { year: number; month: number; day: number };
  /** Latest selectable date (inclusive); days after it render disabled. */
  max?: { year: number; month: number; day: number };
  /**
   * Caption presentation. `"label"` (default) shows the visible range as a
   * plain view-trigger button; `"dropdown"` swaps it for native month and year
   * `<select>` controls. Component-owned — not forwarded to the machine.
   */
  captionLayout?: "label" | "dropdown";
};

static function toDateValue(date: { year: number; month: number; day: number }): DateValue {
  return new CalendarDate(date.year, date.month, date.day);
}

static function toPlain(date: DateValue) {
  return { year: date.year, month: date.month, day: date.day };
}

<machine-props/pickedProps from=input pick=datePickerMachine.props
  open=true
  inline=true
  closeOnSelect=false
  onValueChange(details: datePickerMachine.ValueChangeDetails) {
    input.onValueChange?.(details);
    input.valueChange?.(details.value.map(toPlain));
  }/>
<const/machineProps=() => ({
  ...pickedProps(),
  value: input.value?.map(toDateValue),
  min: input.min ? toDateValue(input.min) : undefined,
  max: input.max ? toDateValue(input.max) : undefined,
})/>
<service/service machine=() => datePickerMachine.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  datePickerMachine.connect(service, normalizeProps)
  service=service
/>

// `value`/`min`/`max` are deliberately remapped to plain { year, month, day }
// objects on this component's public Input (see the note above it), so `input`
// does not satisfy `splitProps`'s `Partial<DatePickerProps>` constraint. All
// three are machine-owned keys that `splitProps` would strip from the leftover
// anyway — drop them first and the call type-checks on the keys it actually
// partitions. `toDateValue()` is what feeds real DateValues to the machine.
<const/splitSource=() => {
  const { value, min, max, ...rest } = input;
  return rest;
}/>
<const/nativeAttrs=() =>
  stripOwnProps(
    datePickerMachine.splitProps(splitSource())[1],
    "class",
    "valueChange",
    "captionLayout",
  )
>

<const/captionLayout=(input.captionLayout ?? "label")/>

// Visible month's short name, matching the month <select>'s option labels.
<const/monthLabel=() => {
  const month = api().visibleRange.start.month;
  return api().getMonths({ format: "short" }).find((m) => m.value === month)?.label ?? String(month);
}/>

<const/weeks=() =>
  api().weeks.map((week) =>
    week.map((date) => ({
      cell: api().getDayTableCellProps({ value: date }),
      trigger: api().getDayTableCellTriggerProps({ value: date }),
      label: String(date.day),
    })),
  )
/>

<div
  ...nativeAttrs()
  ...api().getRootProps()
  data-slot="calendar"
  class=cn(
    "p-2 [--cell-radius:var(--radius-md)] [--cell-size:--spacing(7)] group/calendar bg-background in-data-[slot=card-content]:bg-transparent in-data-[slot=popover-content]:bg-transparent",
    input.class,
  )
>
  <div ...api().getContentProps() data-slot="calendar-content" class="relative flex flex-col gap-4">
    <div class="absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1">
      <button
        ...api().getPrevTriggerProps()
        data-slot="calendar-prev-trigger"
        class=cn(buttonVariants({ variant: "ghost", size: "icon-sm" }), "size-(--cell-size) p-0 select-none aria-disabled:opacity-50")
      >
        <Icon name="ChevronLeft" class="mu-rtl-flip"/>
        <span class="sr-only">Previous</span>
      </button>
      <if=captionLayout === "dropdown">
        <div
          data-slot="calendar-dropdowns"
          class="flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium"
        >
          <div
            data-slot="calendar-dropdown-root"
            class="has-focus:border-ring border-input has-focus:ring-ring/50 border has-focus:ring-3 relative rounded-(--cell-radius)"
          >
            <select
              ...api().getMonthSelectProps()
              data-slot="calendar-month-select"
              class="absolute inset-0 bg-popover opacity-0"
            >
              <for|month| of=api().getMonths({ format: "short" })>
                <option value=month.value disabled=month.disabled>${month.label}</option>
              </for>
            </select>
            <span
              aria-hidden="true"
              data-slot="calendar-caption-label"
              class="h-6 pr-1 pl-1.5 flex items-center gap-1 rounded-(--cell-radius) text-sm font-medium select-none [&>svg]:size-3.5 [&>svg]:text-muted-foreground"
            >
              ${monthLabel()}
              <Icon name="ChevronDown"/>
            </span>
          </div>
          <div
            data-slot="calendar-dropdown-root"
            class="relative rounded-(--cell-radius)"
          >
            <select
              ...api().getYearSelectProps()
              data-slot="calendar-year-select"
              class="absolute inset-0 bg-popover opacity-0"
            >
              <for|year| of=api().getYears()>
                <option value=year.value disabled=year.disabled>${year.label}</option>
              </for>
            </select>
            <span
              aria-hidden="true"
              data-slot="calendar-caption-label"
              class="flex items-center gap-1 rounded-(--cell-radius) text-sm font-medium select-none [&>svg]:size-3.5 [&>svg]:text-muted-foreground"
            >
              ${String(api().visibleRange.start.year)}
              <Icon name="ChevronDown"/>
            </span>
          </div>
        </div>
      </if>
      <else>
        <button
          ...api().getViewTriggerProps()
          data-slot="calendar-view-trigger"
          class="text-sm font-medium select-none"
        >
          ${api().visibleRangeText.formatted}
        </button>
      </else>
      <button
        ...api().getNextTriggerProps()
        data-slot="calendar-next-trigger"
        class=cn(buttonVariants({ variant: "ghost", size: "icon-sm" }), "size-(--cell-size) p-0 select-none aria-disabled:opacity-50")
      >
        <Icon name="ChevronRight" class="mu-rtl-flip"/>
        <span class="sr-only">Next</span>
      </button>
    </div>
    <table ...api().getTableProps() data-slot="calendar-table" class="w-full border-collapse">
      <thead ...api().getTableHeadProps() data-slot="calendar-table-head">
        <tr class="flex">
          <for|weekDay| of=api().weekDays>
            <th class="w-(--cell-size) flex-1 rounded-(--cell-radius) text-[0.8rem] font-normal text-muted-foreground select-none">
              ${weekDay.narrow}
              <span class="sr-only">${weekDay.long}</span>
            </th>
          </for>
        </tr>
      </thead>
      <tbody ...api().getTableBodyProps() data-slot="calendar-table-body">
        <for|week, i| of=weeks() by=(_, i) => `week:${i}`>
          <tr class="mt-2 flex w-full">
            <for|day, j| of=week by=(_, j) => `day:${j}`>
              <td
                ...day.cell
                data-slot="calendar-cell"
                class="group/day relative aspect-square h-full w-full rounded-(--cell-radius) p-0 text-center select-none [&:has([data-in-range])]:bg-muted first:[&:has([data-in-range])]:rounded-l-(--cell-radius) last:[&:has([data-in-range])]:rounded-r-(--cell-radius)"
              >
                <button
                  ...day.trigger
                  data-slot="calendar-day"
                  class="relative isolate z-10 flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 border-0 leading-none font-normal text-foreground data-[today]:bg-muted data-[outside-range]:text-muted-foreground data-[outside-range]:opacity-50 group-data-[focus]/day:relative group-data-[focus]/day:z-10 group-data-[focus]/day:border-ring group-data-[focus]/day:ring-[3px] group-data-[focus]/day:ring-ring/50 data-[range-end]:rounded-(--cell-radius) data-[range-end]:rounded-r-(--cell-radius) data-[range-end]:bg-primary data-[range-end]:text-primary-foreground data-[in-range]:rounded-none data-[in-range]:bg-muted data-[in-range]:text-foreground data-[range-start]:rounded-(--cell-radius) data-[range-start]:rounded-l-(--cell-radius) data-[range-start]:bg-primary data-[range-start]:text-primary-foreground data-selected:bg-primary data-selected:text-primary-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 dark:hover:text-foreground"
                >
                  ${day.label}
                </button>
              </td>
            </for>
          </tr>
        </for>
      </tbody>
    </table>
  </div>
</div>

<return=api>
